const state = {
  user: null, view: 'dashboard', dashboard: null, theme: localStorage.getItem('mk-theme') || 'dark',
  tests: [], currentTest: null, runner: null, runnerTimer: null, testFilter: 'All',
  currentAffairs: [], materials: [], questions: [], library: null, results: [], adminStats: null,
  filters: { exam: '', subject: '', topic: '', difficulty: '', q: '' },
  caCategory: '', searchResults: [], lastResult: null
};

const app = document.querySelector('#app');
const toastEl = document.querySelector('#toast');
const modalRoot = document.querySelector('#modal-root');
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[c]));
const formatDate = (value) => value ? new Date(value).toLocaleDateString('hi-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : '—';
const formatTime = (seconds) => `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(Math.max(0, seconds % 60)).padStart(2, '0')}`;
const label = (value) => String(value || '').replace(/-/g, ' ');

async function api(path, options = {}) {
  const response = await fetch(path, { headers: { 'Content-Type': 'application/json', ...(options.headers || {}) }, ...options });
  let body = {};
  try { body = await response.json(); } catch { body = {}; }
  if (!response.ok) {
    if (response.status === 401 && state.user) { state.user = null; render(); }
    throw new Error(body.error || 'Request पूरी नहीं हुई।');
  }
  return body;
}

function toast(message, tone = 'normal') {
  toastEl.textContent = message; toastEl.className = `toast show ${tone}`;
  window.clearTimeout(toast.timer); toast.timer = window.setTimeout(() => { toastEl.className = 'toast'; }, 3200);
}

function setTheme(theme) { state.theme = theme; localStorage.setItem('mk-theme', theme); document.documentElement.dataset.theme = theme; }
setTheme(state.theme);

function renderAuth(mode = 'login', authRole = 'student', error = '') {
  app.innerHTML = `<main class="auth-page">
    <div class="auth-wrap">
      <section class="auth-pitch">
        <div class="logo-line"><span class="brand-mark">M</span><span>MKRAAJLTP</span></div>
        <div class="eyebrow" style="margin-top:54px">AI-powered exam preparation</div>
        <h1>अपनी तैयारी को <span class="gradient-text">next level</span> बनाइए।</h1>
        <p>SSC और UPSC के लिए एक focused study space — mock tests, smart revision, current affairs और आपकी गलतियों से सीखने वाला study agent.</p>
        <div class="feature-row"><span class="feature-chip">◈ Personalized Plan</span><span class="feature-chip">◉ Exam-grade Mock Tests</span><span class="feature-chip">⌁ हिंदी-first UI</span></div>
      </section>
      <section class="auth-card">
        <div class="segmented"><button class="${mode === 'login' ? 'active' : ''}" data-auth-mode="login">Login</button><button class="${mode === 'register' ? 'active' : ''}" data-auth-mode="register">नया account</button></div>
        <h2>${mode === 'login' ? 'वापस स्वागत है' : 'अपनी तैयारी शुरू करें'}</h2>
        <p class="sub">${mode === 'login' ? 'अपने study dashboard में सुरक्षित प्रवेश करें।' : 'Free student account बनाकर progress save करें।'}</p>
        <div class="segmented"><button class="${authRole === 'student' ? 'active' : ''}" data-auth-role="student">🎓 Student</button><button class="${authRole === 'admin' ? 'active' : ''}" data-auth-role="admin">◆ Admin</button></div>
        <form id="auth-form" data-mode="${mode}" data-role="${authRole}">
          ${mode === 'register' ? '<div class="field"><label for="auth-name">पूरा नाम</label><input id="auth-name" name="name" required minlength="2" placeholder="जैसे — Ananya Sharma"></div>' : ''}
          <div class="field"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" autocomplete="email" required placeholder="you@example.com"></div>
          <div class="field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="${mode === 'login' ? 'current-password' : 'new-password'}" required minlength="8" placeholder="कम से कम 8 characters"></div>
          ${mode === 'register' ? '<div class="field"><label for="auth-exam">Target exam</label><select id="auth-exam" name="exam"><option value="SSC">SSC</option><option value="UPSC">UPSC</option></select></div>' : ''}
          <div class="form-error">${esc(error)}</div>
          <button class="btn btn-primary btn-block" type="submit">${mode === 'login' ? 'Secure login →' : 'Account बनाएं →'}</button>
        </form>
        <div class="demo-hint">आपका data account-level पर save होता है। Admin access के लिए authorized admin credentials आवश्यक हैं। Password या API key chat में share न करें।</div>
      </section>
    </div>
  </main>`;
}

function navItem(view, icon, text, active = state.view) { return `<button class="nav-btn ${active === view ? 'active' : ''}" data-nav="${view}"><span class="nav-icon">${icon}</span>${text}</button>`; }
function renderShell(content) {
  const isAdmin = state.user.role === 'admin';
  app.innerHTML = `<div class="app-shell">
    <aside class="sidebar" id="sidebar">
      <div class="logo-line"><span class="brand-mark">M</span><span>MKRAAJLTP</span></div>
      <div class="sidebar-nav">
        <div class="nav-label">Workspace</div>
        ${navItem('dashboard', '⌂', 'Dashboard')}
        ${isAdmin ? navItem('admin', '◆', 'Admin CMS') : navItem('tests', '◈', 'Mock Tests')}
        ${!isAdmin ? navItem('materials', '▣', 'Study Material') : navItem('tests', '◈', 'Test Manager')}
        ${!isAdmin ? navItem('questions', '◇', 'Question Bank') : navItem('materials', '▣', 'Material Library')}
        ${!isAdmin ? navItem('current-affairs', '✦', 'Current Affairs') : navItem('current-affairs', '✦', 'Current Affairs')}
        <div class="nav-label">Your progress</div>
        ${!isAdmin ? navItem('results', '↗', 'Results & Analysis') : navItem('leaderboard', '♛', 'Leaderboard')}
        ${!isAdmin ? navItem('library', '▤', 'My Library') : navItem('notifications', '◌', 'Notifications')}
        ${!isAdmin ? navItem('leaderboard', '♛', 'Leaderboard') : ''}
      </div>
      <div class="sidebar-bottom"><div class="user-mini"><div class="avatar">${esc(state.user.avatar || state.user.name?.[0] || 'M')}</div><div><strong>${esc(state.user.name)}</strong><span class="${isAdmin ? 'admin-pill' : ''}">${isAdmin ? 'Authorized Admin' : `${esc(state.user.exam || 'SSC')} Student`}</span></div></div><button class="nav-btn" data-logout>↪ <span>Logout</span></button></div>
    </aside>
    <section class="main">
      <header class="topbar"><div class="search-wrap"><button class="icon-btn mobile-menu" data-sidebar>☰</button><span class="search-glyph">⌕</span><input class="search-input" id="global-search" placeholder="Search material, question, test…" autocomplete="off"><div id="search-results"></div></div><div class="top-actions"><button class="icon-btn desktop-only" data-theme-toggle title="Theme">${state.theme === 'dark' ? '☼' : '☾'}</button><button class="icon-btn" data-nav="notifications" title="Notifications">◌<i class="dot"></i></button><button class="btn btn-secondary desktop-only" data-nav="${isAdmin ? 'admin' : 'tests'}">${isAdmin ? 'CMS खोलें' : 'Test शुरू करें'} ↗</button></div></header>
      <main class="view" id="view">${content}</main>
    </section>
  </div>`;
}

async function render() {
  if (!state.user) { renderAuth(); return; }
  const placeholder = `<div class="view-head"><div><div class="kicker">MKRAAJLTP / ${state.user.role === 'admin' ? 'ADMIN CONSOLE' : 'STUDY SPACE'}</div><h1>Loading workspace…</h1><p>आपकी तैयारी के signals assemble हो रहे हैं।</p></div></div><div class="card empty">थोड़ा इंतज़ार करें…</div>`;
  renderShell(placeholder);
  try {
    if (state.view === 'dashboard') await loadDashboard();
    else if (state.view === 'tests') await loadTests();
    else if (state.view === 'materials') await loadMaterials();
    else if (state.view === 'questions') await loadQuestions();
    else if (state.view === 'current-affairs') await loadCurrentAffairs();
    else if (state.view === 'results') await loadResults();
    else if (state.view === 'library') await loadLibrary();
    else if (state.view === 'leaderboard') await loadLeaderboard();
    else if (state.view === 'notifications') await loadNotifications();
    else if (state.view === 'admin') await loadAdmin();
    else if (state.view === 'runner') renderRunner();
    else if (state.view === 'result') await loadResult(state.resultId);
  } catch (error) { const node = document.querySelector('#view'); if (node) node.innerHTML = `<div class="card empty"><h3>कुछ गड़बड़ हुई</h3><p>${esc(error.message)}</p><button class="btn btn-primary" data-nav="dashboard">Dashboard पर लौटें</button></div>`; }
}

async function loadDashboard() { state.dashboard = await api('/api/dashboard'); renderShell(dashboardHTML(state.dashboard)); }
function dashboardHTML(data) {
  const stats = data.stats || {}; const p = data.progress || {}; const plan = data.plan || { items: [] };
  return `<div class="view-head"><div><div class="kicker">${new Date().toLocaleDateString('hi-IN', { weekday: 'long', day: 'numeric', month: 'long' })}</div><h1>Good morning, ${esc(data.user?.name?.split(' ')[0] || 'Learner')} 👋</h1><p>आज छोटी जीतों को consistent बनाइए। आपका ${esc(data.user?.exam || 'SSC')} workspace ready है।</p></div><div><span class="badge purple">✦ ${data.aiConfigured ? 'Live AI connected' : 'Explainable AI fallback'}</span></div></div>
  <section class="card hero-card"><div class="eyebrow">TODAY'S INTELLIGENT ROUTE</div><h2>${esc(plan.headline || 'आज का plan आपकी performance के हिसाब से तैयार है।')}</h2><p>${esc(plan.reason || 'पहले weak topic, फिर timed practice और अंत में reflection करें।')}</p><div class="hero-actions"><button class="btn btn-teal" data-action="start-daily">आज का test शुरू करें ↗</button><button class="btn btn-secondary" data-action="generate-ai">AI quiz बनाएं ✦</button></div></section>
  <div class="grid grid-4" style="margin-top:17px"><div class="card metric-card"><div class="metric-top"><span>Tests completed</span><span class="metric-icon">◈</span></div><div class="metric-value">${stats.testsCompleted || 0}</div><span style="color:var(--muted);font-size:11px">इस account में</span></div><div class="card metric-card"><div class="metric-top"><span>Accuracy</span><span class="metric-icon">◎</span></div><div class="metric-value">${stats.accuracy || 0}<small style="font-size:15px">%</small></div><span style="color:var(--muted);font-size:11px">attempted answers पर</span></div><div class="card metric-card"><div class="metric-top"><span>Questions solved</span><span class="metric-icon">◇</span></div><div class="metric-value">${stats.questionsSolved || 0}</div><span style="color:var(--muted);font-size:11px">active practice</span></div><div class="card metric-card"><div class="metric-top"><span>Current streak</span><span class="metric-icon">🔥</span></div><div class="metric-value">${stats.streak || 0}<small style="font-size:15px"> days</small></div><span style="color:var(--muted);font-size:11px">keep it alive</span></div></div>
  <div class="grid grid-2"><section><div class="section-heading"><h2>आज का personalized plan</h2><span>${esc(plan.generatedBy || 'Study Agent')}</span></div><div class="card">${(plan.items || []).map((item) => `<div class="plan-card"><div class="plan-dot"></div><div class="plan-time">${esc(item.time)}</div><div><h4>${esc(item.title)}</h4><p>${esc(item.detail)}</p></div></div>`).join('') || '<div class="empty">पहला mock test देने के बाद personalized plan और बेहतर होगा।</div>'}</div></section><section><div class="section-heading"><h2>Performance pulse</h2><span>live from your attempts</span></div><div class="card"><div class="study-focus"><strong>Weak topics</strong><p>${p.weakTopics?.length ? p.weakTopics.map(esc).join(' · ') : 'अभी initial assessment बाकी है।'}</p></div><div class="bar-list">${(p.subjects || []).slice(0, 4).map((row) => `<div class="bar-row"><div class="bar-label"><span>${esc(row.subject)}</span><b>${row.accuracy}%</b></div><div class="progress-bar"><i style="width:${row.accuracy}%"></i></div></div>`).join('') || '<p style="color:var(--muted);font-size:12px">Tests attempt करके subject signals बनाएं।</p>'}</div></div></section></div>
  <div class="grid grid-2"><section><div class="section-heading"><h2>Study Agent से पूछें</h2><span>Hindi-first guidance</span></div><div class="card"><form id="agent-form"><div class="field"><label for="agent-prompt">आपका सवाल</label><textarea id="agent-prompt" name="prompt" placeholder="आज मुझे क्या पढ़ना चाहिए? / मेरी गलतियों पर revision कराओ…" required></textarea></div><button class="btn btn-primary" type="submit">उत्तर पाएं ✦</button></form><div id="agent-answer"></div></div></section><section><div class="section-heading"><h2>Quick actions</h2><span>build momentum</span></div><div class="grid grid-2"><button class="card btn" data-nav="questions" style="text-align:left"><span class="badge purple">PRACTICE</span><h3 style="margin-top:12px">Question Bank</h3><p style="color:var(--muted);font-size:12px">Topic और difficulty filter के साथ।</p></button><button class="card btn" data-nav="current-affairs" style="text-align:left"><span class="badge yellow">DAILY</span><h3 style="margin-top:12px">Current Affairs</h3><p style="color:var(--muted);font-size:12px">Short notes और related MCQs।</p></button></div></section></div>`;
}

async function loadTests() { const exam = state.user.exam || 'SSC'; const data = await api(`/api/tests?exam=${encodeURIComponent(exam)}`); state.tests = data.tests || []; renderShell(testsHTML()); }
function testsHTML() {
  const categories = ['All', ...new Set(state.tests.map((t) => t.category))]; const filtered = state.testFilter === 'All' ? state.tests : state.tests.filter((t) => t.category === state.testFilter);
  return `<div class="view-head"><div><div class="kicker">TEST LAB / ${esc(state.user.exam || 'SSC')}</div><h1>Mock Tests</h1><p>Timer, palette, mark for review और negative marking के साथ real exam simulation.</p></div><button class="btn btn-primary" data-action="custom-test">+ Custom Test</button></div><div class="filter-row">${categories.map((cat) => `<button class="btn ${state.testFilter === cat ? 'btn-primary' : 'btn-secondary'}" data-test-filter="${esc(cat)}">${esc(cat)}</button>`).join('')}</div><div class="grid grid-3">${filtered.map((test) => testCard(test)).join('') || '<div class="empty" style="grid-column:1/-1">इस exam के लिए अभी कोई published test नहीं है।</div>'}</div><div class="section-heading"><h2>Test rules</h2><span>हर test में server-side scoring</span></div><div class="notice">Attempt start करने पर server deadline तय करता है। Answer save browser और server दोनों तरफ होता है। Submit के बाद score, accuracy, subject/topic performance और explanations unlock होंगे।</div>`;
}
function testCard(test) { return `<article class="card test-card"><div><div class="test-top"><span class="badge ${test.category?.includes('AI') ? 'purple' : ''}">${esc(test.category)}</span><span class="badge yellow">${test.premium ? 'PREMIUM' : 'FREE'}</span></div><h3 style="margin-top:14px">${esc(test.title)}</h3><p>${esc(test.description || 'Exam-style practice set with performance insights.')}</p></div><div><div class="test-meta"><span>◫ ${test.questionCount || test.questions?.length || 0} Qs</span><span>◷ ${test.durationMinutes} min</span><span>−${test.negativeMarking} mark</span></div><button class="btn btn-primary btn-block" data-start-test="${test.id}">Instructions देखें →</button></div></article>`; }

async function startTest(testId) {
  const data = await api(`/api/tests/${testId}/start`, { method: 'POST', body: JSON.stringify({}) });
  state.runner = { ...data.attempt, test: data.test, serverNow: data.serverNow }; state.view = 'runner'; renderShell(renderRunner()); startRunnerClock();
}
function renderRunner() {
  const r = state.runner; if (!r) return '<div class="card empty">No active test.</div>'; const q = r.test.questions[r.currentIndex || 0] || r.test.questions[0]; const current = r.currentIndex || 0; const selected = r.answers?.[q.id];
  return `<div class="runner"><div class="runner-top"><div class="runner-title"><div class="kicker">LIVE ATTEMPT / ${esc(r.test.exam)}</div><h1>${esc(r.test.title)}</h1><p>${r.test.questions.length} questions · ${r.test.negativeMarking} negative marking · answers auto-save होते हैं</p></div><div class="timer" id="timer">${formatTime(Math.max(0, Math.floor((new Date(r.deadlineAt) - Date.now()) / 1000)))}</div></div><div class="runner-grid"><section class="card question-card"><div class="question-number">QUESTION ${current + 1} OF ${r.test.questions.length} · ${esc(q.subject)} / ${esc(q.topic)}</div><h2>${esc(q.stem)}</h2><div class="options">${q.options.map((option, index) => `<button class="option ${Number(selected) === index ? 'selected' : ''}" data-answer="${index}"><span class="option-letter">${String.fromCharCode(65 + index)}</span><span>${esc(option)}</span></button>`).join('')}</div><div class="question-bottom"><button class="btn btn-secondary" data-action="toggle-review">${(r.review || []).includes(q.id) ? '★ Review marked' : '☆ Mark for review'}</button><div style="display:flex;gap:8px"><button class="btn btn-secondary" data-action="prev-question" ${current === 0 ? 'disabled' : ''}>← Previous</button>${current === r.test.questions.length - 1 ? '<button class="btn btn-primary" data-action="submit-test">Submit Test ✓</button>' : '<button class="btn btn-primary" data-action="next-question">Next →</button>'}</div></div></section><aside class="card palette-card"><h3>Question palette</h3><div class="palette">${r.test.questions.map((question, index) => `<button class="${index === current ? 'current' : ''} ${r.answers?.[question.id] !== undefined && r.answers?.[question.id] !== null ? 'answered' : ''} ${(r.review || []).includes(question.id) ? 'review' : ''}" data-question-index="${index}">${index + 1}</button>`).join('')}</div><div class="palette-legend"><span class="l-current">Current</span><span class="l-answered">Answered</span><span class="l-review">Marked for review</span></div><div class="notice" style="margin-top:20px">Auto-save active. Browser बंद हो जाए तो इसी device पर attempt resume करें।</div><button class="btn btn-danger btn-block" style="margin-top:12px" data-action="submit-test">Submit Test</button></aside></div></div>`;
}
function startRunnerClock() { clearInterval(state.runnerTimer); state.runnerTimer = setInterval(() => { if (!state.runner) return clearInterval(state.runnerTimer); const remaining = Math.floor((new Date(state.runner.deadlineAt) - Date.now()) / 1000); const timer = document.querySelector('#timer'); if (timer) timer.textContent = formatTime(remaining); if (remaining <= 0) { clearInterval(state.runnerTimer); toast('समय समाप्त — test submit हो रहा है।'); submitTest(true); } }, 1000); }
async function saveAttempt() { if (!state.runner) return; try { await api(`/api/attempts/${state.runner.id}/answers`, { method: 'PUT', body: JSON.stringify({ answers: state.runner.answers || {}, review: state.runner.review || [] }) }); } catch (e) { localStorage.setItem(`mk-attempt-${state.runner.id}`, JSON.stringify({ answers: state.runner.answers, review: state.runner.review })); } }
async function submitTest(auto = false) { if (!state.runner) return; if (!auto && !confirm('क्या आप test submit करना चाहते हैं? Submit के बाद answers बदल नहीं पाएंगे।')) return; clearInterval(state.runnerTimer); const data = await api(`/api/attempts/${state.runner.id}/submit`, { method: 'POST', body: JSON.stringify({}) }); state.runner = null; state.view = 'result'; state.resultId = data.result?.id || data.result?.attemptId; state.lastResult = data.result; await loadResult(state.resultId); }

async function loadResult(id) { const data = await api(`/api/results/${id}`); state.lastResult = data; renderShell(resultHTML(data)); }
function resultHTML(data) { const r = data.result || {}; const perf = data.performance || {}; const resultId = r.id || r.attemptId; return `<div class="view-head"><div><div class="kicker">RESULT / DETAILED ANALYSIS</div><h1>${esc(r.testTitle || 'Test Result')}</h1><p>${formatDate(r.submittedAt || r.createdAt)} · ${r.timeTaken ? formatTime(r.timeTaken) : '—'} time taken · Rank ${r.rank || '—'}</p></div><button class="btn btn-secondary" data-nav="tests">और test दें →</button></div><section class="card result-score"><div class="score-ring" style="--score:${Math.max(0, Math.min(100, r.accuracy || 0))}%"><strong>${r.score ?? 0}</strong><span>score</span></div><div><div class="result-metrics"><div class="result-metric"><b>${r.totalQuestions || 0}</b><span>Total Questions</span></div><div class="result-metric"><b>${r.attempted || 0}</b><span>Attempted</span></div><div class="result-metric"><b class="correct-text">${r.correct || 0}</b><span>Correct</span></div><div class="result-metric"><b class="wrong-text">${r.incorrect || 0}</b><span>Incorrect</span></div><div class="result-metric"><b>${r.unattempted || 0}</b><span>Unattempted</span></div><div class="result-metric"><b>${r.accuracy || 0}%</b><span>Accuracy</span></div><div class="result-metric"><b>${r.percentile || '—'}</b><span>Percentile</span></div><div class="result-metric"><b>${r.timeTaken ? formatTime(r.timeTaken) : '—'}</b><span>Time Taken</span></div></div></div></section><div class="grid grid-2"><section><div class="section-heading"><h2>AI performance analysis</h2><span>performance-based</span></div><div class="card"><div class="study-focus"><strong>${esc(data.plan?.headline || 'आपका next best action')}</strong><p>${esc(data.plan?.reason || '')}</p></div><div class="bar-list">${(perf.topics || []).slice(0, 5).map((x) => `<div class="bar-row"><div class="bar-label"><span>${esc(x.topic)}</span><b>${x.accuracy}%</b></div><div class="progress-bar"><i style="width:${x.accuracy}%"></i></div></div>`).join('') || '<p style="color:var(--muted);font-size:12px">अगले test के बाद topic signals दिखेंगे।</p>'}</div><div class="section-heading" style="margin-top:21px"><h2 style="font-size:14px">Recommended revision</h2></div><ul style="color:var(--muted);font-size:12px;line-height:1.8;padding-left:18px">${(data.plan?.recommendations || ['आपकी mistakes के आधार पर revision करें।']).map((x) => `<li>${esc(x)}</li>`).join('')}</ul></div></section><section><div class="section-heading"><h2>हर question का review</h2><span>${(r.questions || []).length} explanations</span></div><div class="card">${(r.questions || []).map((item, i) => `<div class="review-item"><h4>${i + 1}. ${esc(item.question?.stem)}</h4><div class="answer-line ${item.isCorrect ? 'correct-text' : 'wrong-text'}">${item.isCorrect ? '✓ Correct' : item.attempted ? '✕ Incorrect' : '○ Unattempted'} · आपका answer: ${item.studentAnswer === null || item.studentAnswer === undefined ? '—' : esc(item.question?.options?.[item.studentAnswer])}</div><div class="answer-line correct-text">Correct answer: ${esc(item.question?.options?.[item.correctAnswer])}</div><div class="answer-line">Explanation: ${esc(item.question?.explanation || 'Explanation उपलब्ध नहीं है।')}</div></div>`).join('') || '<div class="empty">Question review unavailable.</div>'}</div></section></div>`; }

async function loadMaterials() { const data = await api(`/api/materials?exam=${encodeURIComponent(state.user.exam || '')}`); state.materials = data.materials || []; renderShell(materialsHTML()); }
function materialsHTML() { return `<div class="view-head"><div><div class="kicker">LEARNING LIBRARY</div><h1>Study Material</h1><p>Exam → Subject → Topic → Chapter के हिसाब से curated notes और files.</p></div><button class="btn btn-secondary" data-action="show-sources">Official sources ↗</button></div><div class="filter-row"><input id="material-search" placeholder="Material search…"><select id="material-exam"><option value="">All exams</option><option value="SSC">SSC</option><option value="UPSC">UPSC</option></select></div><div class="grid grid-2">${state.materials.map((m) => `<article class="card material-card"><div class="material-icon">${m.type === 'PDF' ? '▤' : '✦'}</div><div style="min-width:0;flex:1"><div style="display:flex;justify-content:space-between;gap:8px"><h3>${esc(m.title)}</h3><button class="icon-btn" data-bookmark-type="material" data-bookmark-id="${m.id}" title="Bookmark">☆</button></div><p>${esc(m.description || '')}</p><div class="meta">${esc(m.exam)} · ${esc(m.subject || 'General')} · ${esc(m.topic || 'Core')} · ${esc(m.chapter || 'Quick notes')}</div><div style="display:flex;gap:8px;margin-top:12px"><span class="badge">${esc(m.type || 'Notes')}</span>${m.premium ? '<span class="badge yellow">PREMIUM</span>' : ''}${m.fileAvailable ? `<a class="btn btn-secondary" href="/api/materials/${m.id}/file" target="_blank">Open file ↗</a>` : ''}${m.sourceUrl ? `<a class="btn btn-secondary" href="${esc(m.sourceUrl)}" target="_blank" rel="noreferrer">Source ↗</a>` : ''}</div></div></article>`).join('') || '<div class="empty" style="grid-column:1/-1">अभी material नहीं मिला।</div>'}</div>`; }

async function loadQuestions() { const query = new URLSearchParams(Object.fromEntries(Object.entries(state.filters).filter(([, v]) => v))); const data = await api(`/api/questions?${query}`); state.questions = data.questions || []; renderShell(questionsHTML()); }
function questionsHTML() { return `<div class="view-head"><div><div class="kicker">PRACTICE ENGINE</div><h1>Question Bank</h1><p>Exam, subject, topic, difficulty, year और attempted status के साथ targeted practice.</p></div><button class="btn btn-primary" data-action="quick-practice">Quick Practice ↗</button></div><div class="filter-row"><select data-filter="exam"><option value="">All exams</option><option value="SSC" ${state.filters.exam === 'SSC' ? 'selected' : ''}>SSC</option><option value="UPSC" ${state.filters.exam === 'UPSC' ? 'selected' : ''}>UPSC</option></select><select data-filter="subject"><option value="">All subjects</option>${[...new Set(state.questions.map((q) => q.subject))].map((s) => `<option ${state.filters.subject === s ? 'selected' : ''}>${esc(s)}</option>`).join('')}</select><select data-filter="difficulty"><option value="">All difficulty</option>${['Easy', 'Medium', 'Hard'].map((s) => `<option ${state.filters.difficulty === s ? 'selected' : ''}>${s}</option>`).join('')}</select><input data-filter="q" value="${esc(state.filters.q)}" placeholder="Question/topic search…"><button class="btn btn-secondary" data-action="apply-question-filters">Apply</button></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Question</th><th>Exam</th><th>Topic</th><th>Level</th><th></th></tr></thead><tbody>${state.questions.map((q) => `<tr><td><strong>${esc(q.stem)}</strong></td><td>${esc(q.exam)}</td><td>${esc(q.topic)}</td><td><span class="badge ${q.difficulty === 'Easy' ? '' : 'purple'}">${esc(q.difficulty)}</span></td><td><button class="btn btn-secondary" data-practice-question="${q.id}">Solve</button></td></tr>`).join('') || '<tr><td colspan="5"><div class="empty">No questions found.</div></td></tr>'}</tbody></table></div></div>`; }

async function loadCurrentAffairs() { const query = state.caCategory ? `?category=${encodeURIComponent(state.caCategory)}` : ''; const data = await api(`/api/current-affairs${query}`); state.currentAffairs = data.items || []; state.caCategories = data.categories || []; renderShell(currentAffairsHTML()); }
function currentAffairsHTML() { return `<div class="view-head"><div><div class="kicker">DAILY BRIEF / SOURCE-FIRST</div><h1>Current Affairs</h1><p>Short explanation, detailed context, facts और related MCQs. Changing facts को official source से verify करें।</p></div><span class="badge yellow">${state.currentAffairs.some((x) => x.isDemo) ? 'Demo items marked' : 'Admin published'}</span></div><div class="filter-row"><button class="btn ${!state.caCategory ? 'btn-primary' : 'btn-secondary'}" data-ca-category="">All</button>${(state.caCategories || []).map((cat) => `<button class="btn ${state.caCategory === cat ? 'btn-primary' : 'btn-secondary'}" data-ca-category="${esc(cat)}">${esc(cat)}</button>`).join('')}</div><div class="grid grid-3">${state.currentAffairs.map((item) => `<article class="card ca-card"><span class="badge">${esc(item.category)}</span><h3>${esc(item.title)}</h3><p>${esc(item.shortExplanation)}</p><div class="card-foot"><small style="color:var(--faint)">${formatDate(item.publishedAt)}</small><button class="btn btn-secondary" data-ca-detail="${item.id}">Read brief →</button></div></article>`).join('') || '<div class="empty" style="grid-column:1/-1">आज के लिए admin upload का इंतज़ार है।</div>'}</div>`; }

async function loadResults() { const data = await api('/api/results'); state.results = data.results || []; renderShell(resultsHTML()); }
function resultsHTML() { return `<div class="view-head"><div><div class="kicker">YOUR DATA / REVIEW LOOP</div><h1>Results & Analysis</h1><p>हर attempt के बाद weakness, accuracy, speed और revision route देखें।</p></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Test</th><th>Score</th><th>Accuracy</th><th>Attempted</th><th>Date</th><th></th></tr></thead><tbody>${state.results.map((r) => `<tr><td><strong>${esc(r.testTitle)}</strong></td><td>${r.score}</td><td>${r.accuracy}%</td><td>${r.attempted}/${r.totalQuestions}</td><td>${formatDate(r.submittedAt || r.createdAt)}</td><td><button class="btn btn-secondary" data-result="${r.id || r.attemptId}">Open</button></td></tr>`).join('') || '<tr><td colspan="6"><div class="empty">अभी result नहीं है। पहला test attempt करें।</div></td></tr>'}</tbody></table></div></div>`; }

async function loadLibrary() { const data = await api('/api/library'); state.library = data; renderShell(libraryHTML()); }
function libraryHTML() { const marks = state.library?.bookmarks || []; const notes = state.library?.notes || []; return `<div class="view-head"><div><div class="kicker">PERSONAL SPACE</div><h1>My Library</h1><p>Bookmarks, saved questions और personal notes एक जगह।</p></div><span class="badge purple">${marks.length + notes.length} saved</span></div><div class="grid grid-2"><section><div class="section-heading"><h2>Bookmarks</h2><span>Questions & material</span></div><div class="card">${marks.map((mark) => `<div class="list-row"><div><strong>${esc(mark.item?.title || mark.item?.stem || 'Saved item')}</strong><small>${esc(mark.entityType)} · ${formatDate(mark.createdAt)}</small></div><button class="btn btn-secondary" data-unbookmark-type="${mark.entityType}" data-unbookmark-id="${mark.entityId}">Remove</button></div>`).join('') || '<div class="empty">किसी material या question पर bookmark दबाएं।</div>'}</div></section><section><div class="section-heading"><h2>Personal notes</h2><button class="btn btn-primary" data-action="new-note">+ Note</button></div><div class="card">${notes.map((note) => `<div class="list-row"><div><strong>${esc(note.title || 'My note')}</strong><small>${esc(note.content)} · ${formatDate(note.updatedAt || note.createdAt)}</small></div></div>`).join('') || '<div class="empty">Revision notes यहाँ दिखाई देंगे।</div>'}</div></section></div>`; }

async function loadLeaderboard() { const data = await api('/api/leaderboard?period=overall'); state.leaders = data.leaders || []; renderShell(leaderboardHTML(data)); }
function leaderboardHTML(data) { return `<div class="view-head"><div><div class="kicker">COMMUNITY MOMENTUM</div><h1>Leaderboard</h1><p>Daily, weekly, monthly और overall score में healthy competition.</p></div><div class="filter-row" style="margin:0"><button class="btn btn-primary">Overall</button><button class="btn btn-secondary" data-action="leaderboard-period" data-period="weekly">Weekly</button></div></div><div class="grid grid-2"><section class="card"><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Student</th><th>Score</th><th>Accuracy</th><th>Streak</th></tr></thead><tbody>${state.leaders.map((row) => `<tr><td><span class="rank-num">#${row.rank}</span></td><td><strong>${esc(row.user?.name || 'Student')}</strong></td><td>${row.score ?? row.overallScore ?? 0}</td><td>${row.accuracy || 0}%</td><td>🔥 ${row.streak || 0}</td></tr>`).join('') || '<tr><td colspan="5">No leaderboard data yet.</td></tr>'}</tbody></table></div></section><section class="card"><span class="badge yellow">YOUR POSITION</span><h2 style="font:700 42px Space Grotesk;margin:19px 0 5px">#${data.mine?.rank || '—'}</h2><p style="color:var(--muted);font-size:13px">Tests complete करके और accuracy improve करके ऊपर जाएं। Ranking actual submitted attempts से बनती है।</p></section></div>`; }

async function loadNotifications() { const data = await api('/api/notifications'); state.notifications = data.notifications || []; renderShell(notificationsHTML()); }
function notificationsHTML() { return `<div class="view-head"><div><div class="kicker">UPDATES</div><h1>Notifications</h1><p>Study material, daily quiz, test results और announcements.</p></div></div><div class="card mini-list">${state.notifications.map((n) => `<div class="list-row"><div><strong>${esc(n.title)}</strong><small>${esc(n.body)} · ${formatDate(n.createdAt)}</small></div><span class="badge ${n.type === 'result' ? 'purple' : ''}">${esc(n.type)}</span></div>`).join('') || '<div class="empty">No notifications.</div>'}</div>`; }

async function loadAdmin() { const [stats, materials, tests, questions] = await Promise.all([api('/api/admin/stats'), api('/api/admin/materials'), api(`/api/tests?exam=${encodeURIComponent(state.adminExam || 'SSC')}`), api('/api/admin/questions')]); state.adminStats = stats.stats; state.adminMaterials = materials.materials || []; state.adminTests = tests.tests || []; state.adminQuestions = questions.questions || []; renderShell(adminHTML()); }
function adminHTML() { const s = state.adminStats || {}; return `<div class="view-head"><div><div class="kicker">CONTROL ROOM / AUTHORIZED ADMIN</div><h1>Admin CMS</h1><p>Content lifecycle, AI drafts और exam pattern configuration एक जगह।</p></div><span class="badge yellow">SECURE ADMIN ROUTE</span></div><div class="grid grid-4"><div class="card metric-card"><div class="metric-top"><span>Students</span><span class="metric-icon">♙</span></div><div class="metric-value">${s.students ?? s.users ?? 0}</div></div><div class="card metric-card"><div class="metric-top"><span>Materials</span><span class="metric-icon">▣</span></div><div class="metric-value">${s.materials || 0}</div></div><div class="card metric-card"><div class="metric-top"><span>Questions</span><span class="metric-icon">◇</span></div><div class="metric-value">${s.questions || 0}</div></div><div class="card metric-card"><div class="metric-top"><span>AI review queue</span><span class="metric-icon">✦</span></div><div class="metric-value">${s.pendingAI || 0}</div></div></div><div class="grid grid-2"><section><div class="section-heading"><h2>Study material upload</h2><span>publish only after review</span></div><div class="card"><form id="material-form"><div class="form-grid"><div class="field"><label>Title</label><input name="title" required placeholder="Polity quick notes"></div><div class="field"><label>Exam</label><select name="exam"><option>SSC</option><option>UPSC</option></select></div><div class="field"><label>Subject</label><input name="subject" placeholder="General Awareness"></div><div class="field"><label>Topic</label><input name="topic" placeholder="Indian Polity"></div><div class="field"><label>Chapter</label><input name="chapter" placeholder="Fundamental Rights"></div><div class="field"><label>Type</label><select name="type"><option>PDF</option><option>Notes</option><option>Image</option></select></div></div><div class="field"><label>Description</label><textarea name="description" placeholder="इस material से student क्या सीखेगा?"></textarea></div><div class="field"><label>Official source URL</label><input name="sourceUrl" type="url" placeholder="https://…"></div><div class="field"><label>File (PDF / image / txt, max 5MB)</label><input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt"></div><label style="display:flex;gap:8px;align-items:center;color:var(--muted);font-size:12px"><input name="premium" type="checkbox"> Premium content (future subscription entitlement)</label><div style="margin-top:15px"><button class="btn btn-primary" type="submit">Upload as draft ↑</button></div></form></div></section><section><div class="section-heading"><h2>Mock test builder</h2><span>SSC / UPSC scoring</span></div><div class="card"><form id="test-form"><div class="form-grid"><div class="field"><label>Test title</label><input name="title" required placeholder="SSC Polity Sprint"></div><div class="field"><label>Exam</label><select name="exam"><option>SSC</option><option>UPSC</option></select></div><div class="field"><label>Category</label><select name="category"><option>Full Length Mock Test</option><option>Subject Test</option><option>Topic Test</option><option>Previous Year Paper</option><option>Daily Test</option><option>Weekly Test</option><option>Custom Test</option></select></div><div class="field"><label>Duration (min)</label><input name="durationMinutes" type="number" min="1" value="30"></div><div class="field"><label>Positive marks</label><input name="positiveMarking" type="number" step="0.01" value="1"></div><div class="field"><label>Negative marks</label><input name="negativeMarking" type="number" step="0.01" value="0.25"></div></div><div class="field"><label>Description</label><textarea name="description" placeholder="Test blueprint…"></textarea></div><div class="field"><label>Questions select करें (max 100)</label><div style="max-height:175px;overflow:auto;border:1px solid var(--line);border-radius:12px;padding:9px">${(state.adminQuestions || []).map((q) => `<label style="display:flex;gap:8px;padding:7px;color:var(--muted);font-size:11px"><input type="checkbox" name="questionIds" value="${q.id}"> ${esc(q.stem)}</label>`).join('')}</div></div><button class="btn btn-primary" type="submit">Save as unpublished test</button></form></div></section></div><div class="grid grid-2" style="margin-top:17px"><section><div class="section-heading"><h2>Question bank builder</h2><span>original practice only</span></div><div class="card"><form id="question-form"><div class="form-grid"><div class="field"><label>Exam</label><select name="exam"><option>SSC</option><option>UPSC</option></select></div><div class="field"><label>Subject</label><input name="subject" required placeholder="General Awareness"></div><div class="field"><label>Topic</label><input name="topic" required placeholder="Indian Polity"></div><div class="field"><label>Difficulty</label><select name="difficulty"><option>Easy</option><option>Medium</option><option>Hard</option></select></div></div><div class="field"><label>Question</label><textarea name="stem" required placeholder="Question text…"></textarea></div><div class="form-grid">${[1,2,3,4].map((n) => `<div class="field"><label>Option ${n}</label><input name="option${n}" required></div>`).join('')}</div><div class="form-grid"><div class="field"><label>Correct option</label><select name="correctIndex"><option value="0">Option 1</option><option value="1">Option 2</option><option value="2">Option 3</option><option value="3">Option 4</option></select></div><div class="field"><label>Year (optional)</label><input name="year" type="number" placeholder="Original practice"></div></div><div class="field"><label>Explanation</label><textarea name="explanation" required placeholder="आसान भाषा में explanation…"></textarea></div><button class="btn btn-primary" type="submit">Save question draft</button></form></div></section><section><div class="section-heading"><h2>Current affairs upload</h2><span>source required</span></div><div class="card"><form id="current-affairs-form"><div class="field"><label>Title</label><input name="title" required placeholder="आज का exam-relevant update"></div><div class="form-grid"><div class="field"><label>Category</label><select name="category"><option>National</option><option>International</option><option>Polity</option><option>Economy</option><option>Science & Technology</option><option>Environment</option><option>Defence</option><option>Awards</option><option>Sports</option><option>Government Schemes</option></select></div><div class="field"><label>Source label</label><input name="sourceLabel" required placeholder="PIB / Ministry / official release"></div></div><div class="field"><label>Short explanation</label><textarea name="shortExplanation" required placeholder="2–3 line exam summary…"></textarea></div><div class="field"><label>Detailed explanation</label><textarea name="detailedExplanation" placeholder="Context, impact और exam angle…"></textarea></div><div class="field"><label>Important facts (one per line)</label><textarea name="importantFacts" placeholder="Fact 1\nFact 2\nFact 3"></textarea></div><div class="field"><label>Official source URL</label><input name="sourceUrl" type="url" required placeholder="https://pib.gov.in/…"></div><button class="btn btn-primary" type="submit">Publish current affair</button></form></div></section></div><div class="section-heading"><h2>Content moderation</h2><span>publish / unpublish</span></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Material</th><th>Taxonomy</th><th>Status</th><th>Action</th></tr></thead><tbody>${(state.adminMaterials || []).map((m) => `<tr><td><strong>${esc(m.title)}</strong><small style="display:block;color:var(--faint)">${esc(m.type || '')}</small></td><td>${esc(m.exam)} · ${esc(m.subject || '—')} · ${esc(m.topic || '—')} · ${esc(m.chapter || '—')}</td><td><span class="badge ${m.published ? '' : 'yellow'}">${m.published ? 'Published' : 'Draft'}</span></td><td><button class="btn btn-secondary" data-toggle-material="${m.id}" data-published="${m.published}">${m.published ? 'Unpublish' : 'Publish'}</button><button class="btn btn-secondary" data-delete-material="${m.id}" style="margin-left:5px">Delete</button></td></tr>`).join('') || '<tr><td colspan="4">No materials.</td></tr>'}</tbody></table></div></div>`; }

function showModal(title, body, actions = '') { modalRoot.innerHTML = `<div class="modal-backdrop" data-close-modal><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${title}</h2></div><button class="close" data-close-modal>×</button></div>${body}<div class="modal-actions">${actions}</div></section></div>`; }
function closeModal() { modalRoot.innerHTML = ''; }

async function showCA(id) { const item = state.currentAffairs.find((x) => x.id === id); if (!item) return; showModal(esc(item.title), `<span class="badge">${esc(item.category)}</span><p style="color:var(--muted);line-height:1.7;margin-top:17px">${esc(item.detailedExplanation || item.shortExplanation)}</p><h3 style="font-size:14px;margin-top:21px">Important facts</h3><ul style="color:var(--muted);line-height:1.8;font-size:12px">${(item.importantFacts || []).map((x) => `<li>${esc(x)}</li>`).join('')}</ul>${item.sourceUrl ? `<a class="btn btn-secondary" href="${esc(item.sourceUrl)}" target="_blank" rel="noreferrer">Official source ↗</a>` : ''}<div class="notice" style="margin-top:17px">Related MCQ: ${esc(item.mcqs?.[0]?.question || 'Admin ने अभी MCQ नहीं जोड़ा है।')}</div>`, '<button class="btn btn-primary" data-close-modal>समझ गया</button>'); }
async function practiceQuestion(id) { const q = state.questions.find((x) => x.id === id) || (await api('/api/questions')).questions.find((x) => x.id === id); if (!q) return; showModal('Practice question', `<span class="badge">${esc(q.exam)} · ${esc(q.topic)}</span><h3 style="font-size:18px;line-height:1.45;margin:17px 0">${esc(q.stem)}</h3><div class="options" id="practice-options">${q.options.map((o, i) => `<button class="option" data-practice-answer="${i}"><span class="option-letter">${String.fromCharCode(65 + i)}</span><span>${esc(o)}</span></button>`).join('')}</div><div id="practice-feedback"></div>`, '<button class="btn btn-secondary" data-close-modal>Close</button>'); modalRoot.querySelectorAll('[data-practice-answer]').forEach((button) => button.addEventListener('click', async () => { modalRoot.querySelectorAll('[data-practice-answer]').forEach((x) => { x.disabled = true; }); const result = await api(`/api/questions/${id}/practice`, { method: 'POST', body: JSON.stringify({ answer: Number(button.dataset.practiceAnswer) }) }); modalRoot.querySelector('#practice-feedback').innerHTML = `<div class="notice" style="margin-top:17px;color:${result.isCorrect ? 'var(--success)' : 'var(--danger)'}">${result.isCorrect ? '✓ सही answer' : '✕ यह answer सही नहीं है'}<br><span style="color:var(--muted)">Correct: ${esc(q.options[result.correctAnswer])}<br>${esc(result.explanation || '')}</span></div>`; })); }

async function handleAuthSubmit(form) { const data = Object.fromEntries(new FormData(form)); try { const result = await api(`/api/auth/${form.dataset.mode}`, { method: 'POST', body: JSON.stringify({ ...data, role: form.dataset.role }) }); state.user = result.user; state.view = 'dashboard'; toast('Secure login successful'); await render(); } catch (error) { renderAuth(form.dataset.mode, form.dataset.role, error.message); } }
async function fileToBase64(file) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(file); }); }

async function handleMaterialForm(form) { const data = Object.fromEntries(new FormData(form)); const file = form.querySelector('[name=file]').files[0]; if (file) data.fileData = await fileToBase64(file); data.fileName = file?.name || ''; data.premium = form.querySelector('[name=premium]').checked; await api('/api/admin/materials', { method: 'POST', body: JSON.stringify(data) }); toast('Material draft upload हो गया'); await loadAdmin(); }
async function handleTestForm(form) { const data = Object.fromEntries(new FormData(form)); data.questionIds = [...form.querySelectorAll('[name=questionIds]:checked')].map((x) => x.value); data.durationMinutes = Number(data.durationMinutes); data.positiveMarking = Number(data.positiveMarking); data.negativeMarking = Number(data.negativeMarking); await api('/api/admin/tests', { method: 'POST', body: JSON.stringify(data) }); toast('Test draft save हो गया'); await loadAdmin(); }
async function handleQuestionForm(form) { const data = Object.fromEntries(new FormData(form)); data.options = [data.option1, data.option2, data.option3, data.option4]; data.correctIndex = Number(data.correctIndex); data.year = data.year ? Number(data.year) : null; data.source = 'Original practice question — not a previous-year paper'; await api('/api/admin/questions', { method: 'POST', body: JSON.stringify(data) }); toast('Question save हो गया'); await loadAdmin(); }
async function handleCurrentAffairsForm(form) { const data = Object.fromEntries(new FormData(form)); data.importantFacts = String(data.importantFacts || '').split('\n').map((item) => item.trim()).filter(Boolean); await api('/api/admin/current-affairs', { method: 'POST', body: JSON.stringify(data) }); toast('Current affair publish हो गया'); form.reset(); await loadAdmin(); }

async function globalSearch(value) {
  if (!value.trim()) { document.querySelector('#search-results')?.remove(); return; }
  const term = value.trim().toLowerCase();
  const [materials, tests, questions, affairs, catalog] = await Promise.all([
    api(`/api/materials?exam=${encodeURIComponent(state.user.exam || '')}&q=${encodeURIComponent(value)}`),
    api(`/api/tests?exam=${encodeURIComponent(state.user.exam || '')}`),
    api(`/api/questions?exam=${encodeURIComponent(state.user.exam || '')}&q=${encodeURIComponent(value)}`),
    api('/api/current-affairs'), api('/api/catalog')
  ]);
  const results = [
    ...(materials.materials || []).map((x) => ({ type: 'material', id: x.id, title: x.title, description: x.description || x.topic || '' })),
    ...(tests.tests || []).filter((x) => `${x.title} ${x.description} ${x.category}`.toLowerCase().includes(term)).map((x) => ({ type: 'test', id: x.id, title: x.title, description: x.description || x.category || '' })),
    ...(questions.questions || []).map((x) => ({ type: 'question', id: x.id, title: x.stem, description: `${x.subject} · ${x.topic}` })),
    ...(affairs.items || []).filter((x) => `${x.title} ${x.shortExplanation} ${x.category}`.toLowerCase().includes(term)).map((x) => ({ type: 'current_affair', id: x.id, title: x.title, description: x.category })),
    ...(catalog.courses || []).filter((x) => `${x.title} ${x.description} ${x.exam}`.toLowerCase().includes(term)).map((x) => ({ type: 'course', id: x.id, title: x.title, description: x.description || x.exam }))
  ].slice(0, 30);
  const wrap = document.querySelector('.search-wrap'); if (!wrap) return;
  let node = document.querySelector('#search-results');
  if (!node) { node = document.createElement('div'); node.id = 'search-results'; node.style.cssText = 'position:absolute;top:50px;left:0;right:0;background:var(--panel-solid);border:1px solid var(--line);border-radius:14px;z-index:30;overflow:hidden;box-shadow:var(--shadow)'; wrap.append(node); }
  node.innerHTML = results.length ? results.slice(0, 7).map((x) => `<button class="list-row" style="border:0;width:100%;text-align:left;background:transparent;padding:12px" data-search-type="${x.type}" data-search-id="${x.id}"><span><strong>${esc(x.title)}</strong><small>${esc(x.type)} · ${esc(x.description)}</small></span></button>`).join('') : '<div style="padding:16px;color:var(--muted);font-size:12px">कोई relevant result नहीं।</div>';
}

async function navigate(view) { if (state.runner && view !== 'runner' && !confirm('Active test चल रहा है। बाहर निकलने पर attempt resume करना होगा। जारी रखें?')) return; clearInterval(state.runnerTimer); state.view = view; document.querySelector('#sidebar')?.classList.remove('open'); await render(); }

// One event layer keeps the responsive shell stable after every view change.
document.addEventListener('submit', async (event) => { event.preventDefault(); const form = event.target; try { if (form.id === 'auth-form') await handleAuthSubmit(form); else if (form.id === 'agent-form') { const data = await api('/api/ai/ask', { method: 'POST', body: JSON.stringify({ prompt: form.prompt.value }) }); document.querySelector('#agent-answer').innerHTML = `<div class="notice" style="margin-top:15px"><b>${esc(data.provider || 'Study Agent')}</b><br>${esc(data.answer)}</div>`; } else if (form.id === 'material-form') await handleMaterialForm(form); else if (form.id === 'test-form') await handleTestForm(form); else if (form.id === 'question-form') await handleQuestionForm(form); else if (form.id === 'current-affairs-form') await handleCurrentAffairsForm(form); } catch (error) { toast(error.message, 'error'); } });
document.addEventListener('click', async (event) => {
  const target = event.target.closest('button, a, [data-nav], [data-action], [data-start-test], [data-practice-question], [data-result], [data-ca-detail]'); if (!target) return;
  try {
    if (target.matches('[data-auth-mode]')) { renderAuth(target.dataset.authMode, document.querySelector('#auth-form')?.dataset.role || 'student'); return; }
    if (target.matches('[data-auth-role]')) { renderAuth(document.querySelector('#auth-form')?.dataset.mode || 'login', target.dataset.authRole); return; }
    if (target.matches('[data-nav]')) return navigate(target.dataset.nav);
    if (target.matches('[data-logout]')) { await api('/api/auth/logout', { method: 'POST' }); state.user = null; state.runner = null; renderAuth(); return; }
    if (target.matches('[data-theme-toggle]')) { setTheme(state.theme === 'dark' ? 'light' : 'dark'); render(); return; }
    if (target.matches('[data-sidebar]')) { document.querySelector('#sidebar')?.classList.toggle('open'); return; }
    if (target.matches('[data-test-filter]')) { state.testFilter = target.dataset.testFilter; document.querySelector('#view').innerHTML = testsHTML(); return; }
    if (target.matches('[data-start-test]')) { await startTest(target.dataset.startTest); return; }
    if (target.matches('[data-answer]')) { const q = state.runner.test.questions[state.runner.currentIndex || 0]; state.runner.answers[q.id] = Number(target.dataset.answer); await saveAttempt(); document.querySelector('#view').innerHTML = renderRunner(); return; }
    if (target.matches('[data-question-index]')) { state.runner.currentIndex = Number(target.dataset.questionIndex); document.querySelector('#view').innerHTML = renderRunner(); return; }
    if (target.matches('[data-action="next-question"]')) { state.runner.currentIndex = Math.min(state.runner.test.questions.length - 1, (state.runner.currentIndex || 0) + 1); document.querySelector('#view').innerHTML = renderRunner(); return; }
    if (target.matches('[data-action="prev-question"]')) { state.runner.currentIndex = Math.max(0, (state.runner.currentIndex || 0) - 1); document.querySelector('#view').innerHTML = renderRunner(); return; }
    if (target.matches('[data-action="toggle-review"]')) { const q = state.runner.test.questions[state.runner.currentIndex || 0]; state.runner.review = state.runner.review || []; state.runner.review = state.runner.review.includes(q.id) ? state.runner.review.filter((x) => x !== q.id) : [...state.runner.review, q.id]; await saveAttempt(); document.querySelector('#view').innerHTML = renderRunner(); return; }
    if (target.matches('[data-action="submit-test"]')) { await submitTest(); return; }
    if (target.matches('[data-action="start-daily"]')) { state.view = 'tests'; state.testFilter = 'Daily Test'; await render(); return; }
    if (target.matches('[data-action="generate-ai"]')) { const data = await api('/api/ai/generate-quiz', { method: 'POST', body: JSON.stringify({ exam: state.user.exam, count: 10 }) }); toast('Performance-based quiz तैयार है'); await startTest(data.test.id); return; }
    if (target.matches('[data-action="custom-test"]')) { showModal('Custom Test', '<p style="color:var(--muted);font-size:13px;line-height:1.6">Custom test builder में exam, topic, difficulty और question count चुनें।</p><div class="field"><label>Question count</label><input id="custom-count" type="number" value="10" min="5" max="30"></div>', '<button class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary" data-create-custom>Generate</button>'); return; }
    if (target.matches('[data-create-custom]')) { const count = Number(document.querySelector('#custom-count').value); closeModal(); const data = await api('/api/tests/custom', { method: 'POST', body: JSON.stringify({ exam: state.user.exam, count, durationMinutes: count * 2, title: `${state.user.exam} Custom Practice` }) }); await startTest(data.test.id); return; }
    if (target.matches('[data-ca-category]')) { state.caCategory = target.dataset.caCategory; await loadCurrentAffairs(); return; }
    if (target.matches('[data-ca-detail]')) { await showCA(target.dataset.caDetail); return; }
    if (target.matches('[data-practice-question]')) { await practiceQuestion(target.dataset.practiceQuestion); return; }
    if (target.matches('[data-action="quick-practice"]')) { const q = state.questions[0]; if (q) await practiceQuestion(q.id); return; }
    if (target.matches('[data-result]')) { state.view = 'result'; state.resultId = target.dataset.result; await loadResult(state.resultId); return; }
    if (target.matches('[data-bookmark-type]') || target.matches('[data-unbookmark-type]')) { const type = target.dataset.bookmarkType || target.dataset.unbookmarkType; const entityId = target.dataset.bookmarkId || target.dataset.unbookmarkId; const data = await api('/api/bookmarks', { method: 'POST', body: JSON.stringify({ entityType: type, entityId }) }); toast(data.bookmarked ? 'Library में save हुआ' : 'Bookmark हटाया गया'); if (state.view === 'library') await loadLibrary(); return; }
    if (target.matches('[data-action="new-note"]')) { showModal('Personal note', '<div class="field"><label>Title</label><input id="note-title" placeholder="My revision note"></div><div class="field"><label>Note</label><textarea id="note-content" required placeholder="आज क्या याद रखना है?"></textarea></div>', '<button class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary" data-save-note>Save</button>'); return; }
    if (target.matches('[data-save-note]')) { await api('/api/notes', { method: 'POST', body: JSON.stringify({ title: document.querySelector('#note-title').value, content: document.querySelector('#note-content').value, entityType: 'general', entityId: 'general' }) }); closeModal(); toast('Note save हो गया'); await loadLibrary(); return; }
    if (target.matches('[data-action="leaderboard-period"]')) { const data = await api(`/api/leaderboard?period=${target.dataset.period}`); state.leaders = data.leaders || []; document.querySelector('#view').innerHTML = leaderboardHTML(data); return; }
    if (target.matches('[data-toggle-material]')) { await api(`/api/admin/materials/${target.dataset.toggleMaterial}`, { method: 'PATCH', body: JSON.stringify({ published: target.dataset.published !== 'true' }) }); toast('Publish status update हुआ'); await loadAdmin(); return; }
    if (target.matches('[data-delete-material]')) { if (!confirm('Material delete करें?')) return; await api(`/api/admin/materials/${target.dataset.deleteMaterial}`, { method: 'DELETE' }); toast('Material delete हुआ'); await loadAdmin(); return; }
    if (target.matches('[data-close-modal]')) { closeModal(); return; }
  } catch (error) { toast(error.message, 'error'); }
});
document.addEventListener('input', (event) => { if (event.target.id === 'global-search') { clearTimeout(state.searchTimer); state.searchTimer = setTimeout(() => globalSearch(event.target.value), 250); } });
document.addEventListener('change', (event) => { if (event.target.matches('[data-filter]')) state.filters[event.target.dataset.filter] = event.target.value; if (event.target.id === 'material-search' || event.target.id === 'material-exam') { const term = document.querySelector('#material-search')?.value?.toLowerCase() || ''; const exam = document.querySelector('#material-exam')?.value || ''; document.querySelectorAll('.material-card').forEach((card) => { card.style.display = (!term || card.textContent.toLowerCase().includes(term)) && (!exam || card.textContent.includes(exam)) ? '' : 'none'; }); } });
document.addEventListener('keydown', (event) => { if (state.view === 'runner' && !event.ctrlKey && !event.metaKey && ['1','2','3','4'].includes(event.key)) { const button = document.querySelector(`[data-answer="${Number(event.key) - 1}"]`); button?.click(); } });

(async function boot() { try { const data = await api('/api/me'); state.user = data.user; if (state.user) await render(); else renderAuth(); } catch { renderAuth(); } })();
